"""Generate ``ci.toml`` and the canonical ``./ci`` entry point."""

from __future__ import annotations

import json
import os
import stat
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from .config import PROFILES, STAGE_NAMES
from .detect import Detection, detect_project, require_audit_command
from .errors import ConfigError

SHIM = """#!/bin/sh
# Canonical ci-fabric entry point. Generated by `ci-fabric init`.
# Local-only: no network service or hosted CI is involved.
set -eu
ROOT=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)

# 1. Editable install in the repository virtual environment (preferred).
if [ -x "$ROOT/.venv/bin/python" ] && \
   "$ROOT/.venv/bin/python" -c 'import ci_fabric' >/dev/null 2>&1; then
  exec "$ROOT/.venv/bin/python" -m ci_fabric "$@"
fi

# 2. Explicit source checkout.
if [ -n "${CI_FABRIC_SRC:-}" ]; then
  PYTHONPATH="$CI_FABRIC_SRC/src${PYTHONPATH:+:$PYTHONPATH}" exec python3 -m ci_fabric "$@"
fi

# 3. Vendored package inside the repository.
if [ -d "$ROOT/tools/ci-fabric/src/ci_fabric" ]; then
  PYTHONPATH="$ROOT/tools/ci-fabric/src${PYTHONPATH:+:$PYTHONPATH}" exec python3 -m ci_fabric "$@"
fi

# 4. A globally installed console script.
if command -v ci-fabric >/dev/null 2>&1; then
  exec ci-fabric "$@"
fi

echo "ci-fabric is not installed." >&2
echo "Install it into this repository:" >&2
echo "  python3 -m venv .venv && .venv/bin/pip install -e /path/to/ci-fabric" >&2
echo "Or set CI_FABRIC_SRC to the ci-fabric source checkout." >&2
exit 3
"""


@dataclass(slots=True)
class ScaffoldResult:
    detection: Detection
    config_path: Path
    gitignore_updated: bool
    shim_written: bool


def _q(value: str) -> str:
    return json.dumps(value, ensure_ascii=False)


def _string_array(values: list[str], *, indent: str = "  ") -> str:
    if not values:
        return "[]"
    lines = ["["]
    lines.extend(f"{indent}{_q(value)}," for value in values)
    lines.append("]")
    return "\n".join(lines)


def _stage(
    name: str,
    *,
    commands: list[str] | None = None,
    required: bool = True,
    extra: dict[str, Any] | None = None,
) -> str:
    lines = [f"[stages.{name}]", f"required = {'true' if required else 'false'}"]
    if commands:
        lines.append("commands = " + _string_array(commands))
    for key, value in (extra or {}).items():
        if value is None:
            continue
        if isinstance(value, bool):
            lines.append(f"{key} = {'true' if value else 'false'}")
        elif isinstance(value, str):
            lines.append(f"{key} = {_q(value)}")
        elif isinstance(value, (int, float)):
            lines.append(f"{key} = {value}")
        elif isinstance(value, list):
            lines.append(f"{key} = " + _string_array([str(item) for item in value]))
        else:  # pragma: no cover - scaffold input is controlled
            raise ConfigError(f"cannot serialise scaffold value for {key}: {type(value).__name__}")
    return "\n".join(lines) + "\n"


def _project_section(detection: Detection, description: str) -> str:
    lines = [
        "[project]",
        f"name = {_q(detection.name)}",
    ]
    if detection.version_file:
        lines.append(f"version_file = {_q(detection.version_file)}")
    elif detection.version:
        lines.append(f"version = {_q(detection.version)}")
    lines.append(f"version_format = {_q(detection.version_format)}")
    if description:
        lines.append(f"description = {_q(description)}")
    return "\n".join(lines) + "\n"


def _versions_section(detection: Detection) -> str:
    lines: list[str] = []
    for source in detection.version_sources:
        lines.append("[[repository.versions]]")
        lines.append(f"path = {_q(source['path'])}")
        lines.append(f"format = {_q(source['format'])}")
        if source.get("key"):
            lines.append(f"key = {_q(source['key'])}")
        lines.append("")
    return "\n".join(lines)


def render_config(detection: Detection, profile: str) -> str:
    audit_required = profile in {"strict", "release"}
    required_paths = [
        name for name in ("README.md", "LICENSE") if (detection.root / name).is_file()
    ]
    lockfiles = [name for name in detection.lockfiles if name not in {"requirements.txt"}]
    parts: list[str] = [
        "# Generated by ci-fabric. Review every command before relying on it.",
        "# Canonical local entry point: ./ci",
        "",
        "version = 1",
        "",
        _project_section(detection, ""),
        "",
        "[policy]",
        f"profile = {_q(profile)}",
        "fail_fast = true",
        'require_clean_worktree = "release"',
        "keep_runs = 20",
        "require_test_discovery = true",
        f"audit_required = {'true' if audit_required else 'false'}",
        "allow_no_git = false",
        "max_tracked_file_mib = 5.0",
        "",
        "[repository]",
        "required_paths = " + _string_array(required_paths),
        'check_links = "warn"',
        'link_globs = ["**/*.md"]',
        "required_lockfiles = " + _string_array(lockfiles),
        "check_conflict_markers = true",
        "check_license = true",
    ]
    versions = _versions_section(detection)
    if versions:
        parts.extend(["", versions.rstrip()])
    parts.extend(
        [
            "",
            _stage("repository", commands=[], required=True).rstrip(),
            "",
            _stage(
                "security",
                commands=[],
                required=True,
                # "secret_scan" is a stage option name, not a credential value;
                # the hardcoded-password heuristic misreads it.
                extra={"secret_scan": True, "scan_untracked": False, "scan_config": True},  # nosec B105
            ).rstrip(),
            "",
        ]
    )
    for stage in ("format", "lint", "typecheck"):
        if detection.commands.get(stage):
            parts.append(
                _stage(
                    stage,
                    commands=detection.commands[stage],
                    required=True,
                ).rstrip()
            )
            parts.append("")
    for stage in ("unit", "integration", "contract", "e2e"):
        commands = detection.commands.get(stage)
        if not commands:
            continue
        extra: dict[str, Any] = {
            "test_globs": detection.test_globs or [],
            "min_test_files": 1,
            "allow_empty": False,
        }
        if stage == "unit" and detection.junit_path:
            extra["junit_path"] = detection.junit_path
        parts.append(_stage(stage, commands=commands, required=True, extra=extra).rstrip())
        parts.append("")
    if detection.coverage_report:
        extra = {
            "report_path": detection.coverage_report,
        }
        if detection.coverage_min_percent is not None:
            extra["min_percent"] = detection.coverage_min_percent
        parts.append(
            _stage(
                "coverage",
                commands=[f'test -f "{detection.coverage_report}"'],
                required=True,
                extra=extra,
            ).rstrip()
        )
        parts.append("")
    if detection.audits:
        parts.append(
            _stage(
                "audit",
                commands=sorted(set(detection.audits)),
                required=audit_required,
            ).rstrip()
        )
        parts.append("")
    if detection.commands.get("build"):
        extra = {}
        if detection.build_outputs:
            extra["outputs"] = detection.build_outputs
        parts.append(
            _stage(
                "build",
                commands=detection.commands["build"],
                required=True,
                extra=extra,
            ).rstrip()
        )
        parts.append("")
    if detection.package_inputs:
        extra = {
            "strategy": "archive",
            "inputs": detection.package_inputs,
            "output": "{artifacts}/package.tar.gz",
        }
        if detection.package_strip_prefix:
            extra["strip_prefix"] = detection.package_strip_prefix
        parts.append(_stage("package", commands=[], required=True, extra=extra).rstrip())
        parts.append("")
        parts.append(
            _stage(
                "artifact",
                commands=[],
                required=True,
                extra={
                    "verify_archives": True,
                    "scan_secrets": True,
                    "must_contain": detection.package_must_contain,
                },
            ).rstrip()
        )
        parts.append("")
    changelog = "RELEASE_NOTES.md"
    if not (detection.root / changelog).is_file() and (detection.root / "CHANGELOG.md").is_file():
        changelog = "CHANGELOG.md"
    parts.extend(
        [
            "[release]",
            "require_clean = true",
            "require_notes = true",
            f"changelog = {_q(changelog)}",
            'tag_prefix = "v"',
            'output_dir = ".localci/releases"',
            "",
            "[hooks]",
            'pre_commit_stages = ["repository", "format", "security"]',
            'pre_push_stages = ["repository", "format", "lint", "typecheck", "unit", "security"]',
            "",
            "# Deployment is opt-in. Uncomment and adapt one environment.",
            "# [deploy.local]",
            '# strategy = "static"',
            '# public_dir = "."',
            "# port = 0",
            '# health_path = "/"',
            "",
        ]
    )
    return "\n".join(parts)


def ensure_gitignore(root: Path) -> bool:
    path = root / ".gitignore"
    existing = path.read_text(encoding="utf-8") if path.is_file() else ""
    lines = {line.strip() for line in existing.splitlines()}
    missing = [pattern for pattern in (".ci/", ".localci/") if pattern not in lines]
    if not missing:
        return False
    block = [
        "",
        "# ci-fabric local state (never commit)",
        *missing,
        "",
    ]
    content = existing
    if content and not content.endswith("\n"):
        content += "\n"
    content += "\n".join(block)
    path.write_text(content, encoding="utf-8", newline="\n")
    return True


def install_shim(root: Path, *, force: bool = False) -> bool:
    path = root / "ci"
    if path.is_file():
        current = path.read_text(encoding="utf-8")
        if current == SHIM:
            path.chmod(path.stat().st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
            return False
        if not force:
            raise ConfigError(
                f"{path.name} already exists and was not generated by ci-fabric",
                remediation=(
                    "Review it, then pass --force to replace it, or call the package directly."
                ),
            )
    path.write_text(SHIM, encoding="utf-8", newline="\n")
    path.chmod(path.stat().st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
    return True


def scaffold(
    root: Path,
    *,
    profile: str = "standard",
    force: bool = False,
) -> ScaffoldResult:
    root = root.resolve()
    if profile not in PROFILES:
        raise ConfigError(f"profile must be one of {', '.join(PROFILES)}")
    detection = detect_project(root)
    require_audit_command(detection, profile)
    config_path = root / "ci.toml"
    if config_path.exists() and not force:
        raise ConfigError(
            f"configuration already exists: {config_path}",
            remediation="Review it, or pass --force to regenerate (this overwrites ci.toml).",
        )
    content = render_config(detection, profile)
    config_path.write_text(content, encoding="utf-8", newline="\n")
    gitignore_updated = ensure_gitignore(root)
    shim_written = install_shim(root, force=False)
    return ScaffoldResult(
        detection=detection,
        config_path=config_path,
        gitignore_updated=gitignore_updated,
        shim_written=shim_written,
    )


def stage_names() -> tuple[str, ...]:
    return STAGE_NAMES


def python_executable(root: Path) -> str:
    for candidate in (root / ".venv" / "bin" / "python", root / "venv" / "bin" / "python"):
        if candidate.is_file():
            return str(candidate)
    return os.environ.get("PYTHON", "python3")
